import unittest
from metrics import mean


class TestMean(unittest.TestCase):
    def test_mean_single_value(self):
        """Test mean of a single value."""
        self.assertEqual(mean([5]), 5.0)

    def test_mean_multiple_values(self):
        """Test mean of multiple values."""
        self.assertEqual(mean([1, 2, 3, 4, 5]), 3.0)

    def test_mean_decimal_values(self):
        """Test mean with decimal values."""
        self.assertAlmostEqual(mean([1.5, 2.5, 3.5]), 2.5)

    def test_mean_negative_values(self):
        """Test mean with negative values."""
        self.assertEqual(mean([-5, -3, -1]), -3.0)

    def test_mean_mixed_positive_negative(self):
        """Test mean with mixed positive and negative values."""
        self.assertEqual(mean([-10, 0, 10]), 0.0)

    def test_mean_all_zeros(self):
        """Test mean of all zeros."""
        self.assertEqual(mean([0, 0, 0]), 0.0)

    def test_mean_two_values(self):
        """Test mean of two values."""
        self.assertEqual(mean([10, 20]), 15.0)

    def test_mean_large_numbers(self):
        """Test mean with large numbers."""
        self.assertEqual(mean([1000000, 2000000, 3000000]), 2000000.0)

    def test_mean_very_small_numbers(self):
        """Test mean with very small numbers."""
        self.assertAlmostEqual(mean([0.001, 0.002, 0.003]), 0.002)

    def test_mean_empty_list_raises_error(self):
        """Test that mean of empty list raises ValueError."""
        with self.assertRaises(ValueError) as context:
            mean([])
        self.assertEqual(str(context.exception), "no values")

    def test_mean_fractional_result(self):
        """Test mean resulting in a fraction."""
        self.assertAlmostEqual(mean([1, 2, 3]), 2.0)
        self.assertAlmostEqual(mean([1, 2]), 1.5)
        self.assertAlmostEqual(mean([1, 2, 4]), 7/3, places=5)


if __name__ == "__main__":
    unittest.main()
